/*
 * MacRunner 2026-08-29 — СНИМОК ОКРУЖЕНИЯ вместо getenv в рантайме.
 *
 * Почему: отчёты macOS о падении показали один и тот же механизм у ТРЁХ разных
 * процессов — Diablo.exe, UnrealTournament.exe, rpcss.exe:
 *
 *   _os_unfair_lock_recursive_abort <- _os_unfair_lock_lock_slow <- getenv
 *     <- abort_thread <- quit_handler <- _sigtramp        (обработчик сигнала)
 *     <- getenv <- hb_wow64cpu_simulate / hb_jit_helper_exec_interp_ir
 *
 * Наш getenv взял внутренний замок libsystem; в этот момент пришёл сигнал
 * завершения, его обработчик снова вызвал getenv — рекурсивный захват того же
 * замка и аварийный останов. getenv НЕ async-signal-safe и вдобавок берёт замок
 * на каждом обращении, а в движке таких вызовов 254, часть — в самом горячем
 * пути (`hb_arm64_codegen.c` звал его на КАЖДУЮ интерпретируемую команду).
 *
 * Решение: обойти `environ` ОДИН РАЗ в конструкторе — он выполняется при
 * загрузке модуля, когда нет ни потоков, ни обработчиков сигналов, — и сложить
 * значения в собственную таблицу. Дальше чтение гейта это поиск в своей памяти:
 * без замков, без libsystem, безопасно из обработчика сигнала.
 *
 * Кеширование значения на месте вызова (static + флаг) закрывает только горячий
 * путь: первый вызов всё равно идёт в getenv, и если сигнал придёт именно там —
 * авария повторится. Снимок закрывает и это.
 */
#ifndef HB_ENV_H
#define HB_ENV_H

/* Возвращает значение переменной из снимка, либо NULL. Безопасно всегда. */
const char* hb_env(const char* name);

/* Гейт: 1 если переменная задана и не "0"/пусто. */
int hb_env_flag(const char* name, int def);

/* Пересобрать снимок. Нужен ТОЛЬКО тестам, меняющим окружение на ходу. */
void hb_env_refresh(void);

/* Сколько записей в снимке — нужно замеру: цена поиска по имени зависит
 * от их числа, и число обязано печататься рядом с числом наносекунд. */
int hb_env_skolko(void);

#endif /* HB_ENV_H */
